$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$Script=Join-Path (Split-Path -Parent $PSScriptRoot) 'core\deployment\accept-new-computer.ps1';$Root=Join-Path $env:TEMP ('MashiroAcceptance-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $Root|Out-Null
try{$static=@{checks=@(@{name='static-health';level='static';status='passed';evidence=@{}},@{name='gateway-port';level='runtime';status='passed';evidence=@{}},@{name='weixin-help';level='human_confirmed';status='unverified';evidence=@{}})}|ConvertTo-Json -Depth 8 -Compress;$r=(& $Script -RunId fixture-static -ReportPath (Join-Path $Root static.json) -FixtureJson $static)|ConvertFrom-Json;if($r.status-ne'unverified'){throw 'Static health and a port must not become end-to-end success.'};$complete=@{checks=@(@{name='runtime-health';level='runtime';status='passed';evidence=@{}},@{name='weixin-help';level='human_confirmed';status='passed';evidence=@{}},@{name='weixin-plan';level='human_confirmed';status='passed';evidence=@{}},@{name='qq-lifecycle';level='human_confirmed';status='passed';evidence=@{}})}|ConvertTo-Json -Depth 8 -Compress;$deploymentPath=Join-Path $Root deployment.json;@{status='unverified';finishedAt=$null;phases=@{acceptance=@{status='unverified';finishedAt=$null;exitCode=0;error=$null;evidencePaths=@()}}}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $deploymentPath -Encoding UTF8;$acceptancePath=Join-Path $Root pass.json;$r=(& $Script -RunId fixture-pass -ReportPath $acceptancePath -DeploymentReportPath $deploymentPath -FixtureJson $complete)|ConvertFrom-Json;if($r.status-ne'passed'){throw 'Complete human-confirmed evidence must pass.'};$deployment=Get-Content -Raw $deploymentPath|ConvertFrom-Json;if($deployment.status-ne'passed'-or$deployment.phases.acceptance.status-ne'passed'-or$deployment.phases.acceptance.evidencePaths-notcontains$acceptancePath){throw 'Acceptance must update the main deployment report.'};Write-Output 'PASS: acceptance evidence levels cannot overclaim deployment success'}finally{Remove-Item -LiteralPath $Root -Recurse -Force -ErrorAction SilentlyContinue}
